window.MANUAL_TOPICS = [{"slug": "getting-started", "title": "Getting started", "group": "Start Here", "icon": "rocket", "summary": "What you need, the download tools, and your first video.", "text": "VideoLibrary needs macOS 26 (Tahoe) or later on an Apple silicon Mac. It downloads with three free tools that you install once: yt-dlp (does the downloading), FFmpeg (joins video and audio) and Deno (solves YouTube's player challenges). Install the app: follow the install guide . Open Settings ( ⌘ , ) › Tools and click Install & Update All . This uses Homebrew ; if you don't have it, the Tools tab links to it. Click + in the toolbar, paste a link and click Download . Your first library is ~/Movies/VideoLibrary . You can add more anywhere, including on external drives."}, {"slug": "keyboard-shortcuts", "title": "Keyboard shortcuts", "group": "Start Here", "icon": "keyboard", "summary": "Every key the player and the app answer to.", "text": "Play or pause Space K Back or forward 5 seconds ← → Back or forward 10 seconds J L Previous or next frame , . Volume up or down ↑ ↓ Mute M Captions on or off C Full screen F or double-click Picture in Picture I Leave full screen, then the player Esc Play or pause music (song list selected) Space Settings ⌘ ,"}, {"slug": "settings", "title": "Settings", "group": "Start Here", "icon": "settings", "summary": "What each Settings tab holds, and where to find a switch.", "text": "Open Settings with ⌘ , or the gear button in the toolbar. General Player options (full screen, fit window to video, miniplayer) and your libraries, with Import Videos and Add Library Folder… . Captions Caption presets, style, position and motion, with a live preview. See Captions . Downloads Default resolution and quality, the YouTube sign-in and the Nebula sign-in. Suggestions Feed source and type, which library downloads go to, Hide Shorts and the minimum length, and the Google Cloud API option. Music Turn music on, choose one collection or one per library, and hide the music bar when leaving Music. Tools Versions of yt-dlp, FFmpeg and Deno with Install & Update All and Check Again , and the experimental SABR Add-on . Privacy How your data is stored, and Run Security Check , which looks for any plaintext secrets left by older versions and encrypts them. Help Player shortcuts, a link to this manual, and the debug log ( Open Debug Log , Show in Finder , Clear Log )."}, {"slug": "libraries", "title": "Libraries", "group": "Libraries and Downloads", "icon": "drive", "summary": "Folders of videos on any drive, plus importing your own files.", "text": "A library is a folder of videos. VideoLibrary keeps its index in a hidden .VideoLibrary folder inside it, so a library on an external drive works on any Mac you plug it into. Adding and switching Click Add Library Folder in the sidebar (or Settings › General › Libraries) and choose a folder. Click a library in the sidebar to switch to it. The header shows how many videos it has, the space they use and the free space on that drive. A library on a drive that isn't plugged in shows Disconnected . It comes back on its own when you reconnect the drive. Browsing The Uploaders list in the sidebar filters the library to one channel. Sort orders videos by title, uploader, date added, upload date, length or size. Each card shows the video's resolution (480p to 4K), length, upload date, file size and how much you've watched. The search box searches the current library by title and uploader. Right-click a video Play or Play from Beginning . Re-download (or Re-download in HD for low-quality files) replaces the file and keeps its place, date added and watch progress. Share , Save to Downloads : see Getting videos out . Move to Library moves the file and its captions into another library. Delete removes it from the library and deletes its files. Importing your own videos Settings › General › Libraries › Import Videos next to a library adds files you didn't download, like screen recordings or clips. The file name becomes the title and an early frame becomes the thumbnail. Copy Videos into Library… puts a copy in the library's Imported folder. Link Videos Where They Are… leaves the files where they are. Deleting a linked video from the library never deletes your file. Only formats macOS can play are imported (MP4, MOV, M4V…). MKV and WebM files are skipped and listed."}, {"slug": "downloading", "title": "Downloading", "group": "Libraries and Downloads", "icon": "download", "summary": "Add Video's choices, the downloads panel, and how YouTube downloads work.", "text": "Click + in the toolbar to open Add Video . Paste a link from YouTube, Nebula or any of the 1,000+ sites yt-dlp supports. Save to Which library to add it to. Downloads Folder saves just the video to ~/Downloads as \"Title.mp4\" without adding it to a library. Resolution The highest resolution to download: Best Available, 4K, 1440p, 1080p (default), 720p or 480p. Quality Balanced (default), Best (allows 60 fps) or Smaller File. The sheet shows what each means. YouTube sign-in Shows whether a sign-in is saved; Change… opens the sign-in settings. For a playlist link, you can choose to download the whole playlist or just the one video. The downloads panel The arrow button in the toolbar shows active downloads with their progress, size and speed. The title appears as soon as yt-dlp has found the video. You can cancel any download. If a download fails, the panel explains what went wrong in plain language with a button that fixes it: sign in, update the tools, choose a different quality or reconnect a library. Details shows yt-dlp's own output. How YouTube downloads work Videos are saved as H.264 MP4 with AAC audio, so every Mac plays them. YouTube downloads are tried signed out first , because YouTube sometimes gives signed-in accounts only a 360p version. Your sign-in is used only when a video needs it (age-restricted, members-only, or YouTube's \"confirm you're not a bot\" check). If YouTube turns a signed-out download away with its bot check, the app goes straight to your sign-in for the next 30 minutes. Captions are fetched with the video. If YouTube rate-limits them, the video still finishes and the captions are fetched again a few minutes later."}, {"slug": "signing-in", "title": "Signing in", "group": "Libraries and Downloads", "icon": "user", "summary": "Your YouTube and Nebula sign-ins, from a browser or a private window.", "text": "A sign-in is needed for your Suggestions feed, age-restricted and members-only videos, Nebula, and when YouTube asks you to confirm you're not a bot. Set it up in Settings › Downloads . YouTube Sign In to YouTube… opens a private sign-in window. Nothing from it is kept except the YouTube sign-in itself. Import from Browser copies your YouTube sign-in from a browser you're already signed in to: Safari, Chrome, Arc, Dia, Brave, Edge, Firefox, Helium and others, including specific profiles. Safari needs Full Disk Access; the app shows a button that opens that setting. Sign Out forgets the saved YouTube sign-in. Nebula The Nebula section has its own Import from Browser and a field for a Nebula token. YouTube and Nebula sign-ins are stored separately; importing one never replaces the other. Every sign-in is stored encrypted. See Privacy and security ."}, {"slug": "sabr", "title": "360p and SABR", "group": "Libraries and Downloads", "icon": "hd", "summary": "Why some YouTube videos only come in 360p, and how VideoLibrary gets HD anyway.", "text": "YouTube is moving to a new way of streaming video called SABR . For some accounts and some networks (VPNs and datacenter connections in particular), YouTube offers HD only as SABR streams, and the standard download tools can't save those yet. Without help, those downloads come out in 360p. VideoLibrary handles this in steps: It notices SABR as soon as yt-dlp picks a format, before anything downloads . It tries other YouTube clients that often still get regular HD streams: Safari's, then the TV app's. The downloads panel shows \"Getting the HD version…\". Signed-in downloads start with Safari's client anyway, so this step is usually skipped. If the SABR add-on is installed, it downloads the video in HD with that. If none of that works, it saves the 360p version and keeps the download in the panel with an Install SABR Add-on & Retry button. The SABR add-on The add-on is a preview build of yt-dlp with SABR support ( yt-dlp pull request #13515 ). It's experimental, so it's never installed up front: A download offers it when it's needed, as above. You can also install it from Settings › Tools › Experimental . Because it's preview software, you'll be asked several times to confirm. It's about 37 MB, checked against its published checksum when installed, and kept in Application Support. It never replaces your Homebrew yt-dlp, and it's only used for videos limited to SABR. Settings › Tools can update or remove it. brew upgrade doesn't update it. Already have 360p videos? Library cards flag them, and a banner offers Re-download in HD ."}, {"slug": "player", "title": "The player", "group": "Watching", "icon": "play", "summary": "Controls, full screen, Picture in Picture, the miniplayer and frame stepping.", "text": "Click a video to play it. It fills the window; move the pointer to show the controls, and they hide again after a moment. Press Esc or click Library to go back. Videos resume where you left off. Transport bar: play/pause, 10-second skips, volume, playback speed (0.5× to 2×), captions on or off, and full screen. Top bar: the title, uploader, upload date and resolution, plus Picture in Picture and Share . Full screen fills the screen with the same controls floating over the video. Turn on Settings › General › Open videos in full screen to start every video that way. Resize the window to fit each video (Settings › General) removes black bars, then puts the window back to its old size when you leave. Miniplayer: leave an unfinished video and it keeps playing in a small player over the library (turn off with Keep playing in a miniplayer when going back to the library ). Frame stepping: , and . move exactly one frame."}, {"slug": "captions", "title": "Captions", "group": "Watching", "icon": "captions", "summary": "YouTube's automatic captions word by word, and every way to restyle them.", "text": "Captions download with each video when available, including YouTube's automatic ones. VideoLibrary shows automatic captions word by word as they're spoken , two steady lines at a time, instead of YouTube's repeating rolling lines. Settings › Captions has a live preview and: Presets: YouTube, Classic, Large & Clear and Minimal set several options at once. Auto-generated captions: how many lines show at once. Text: size, font, weight and color. Background: one box, a box per line, an outline, or none, and its opacity. Position: bottom or top. Show words as they're spoken , Animate captions (off by default) and Keep captions on screen through short pauses , which stops the box from blinking between sentences. Reset to Defaults puts everything back."}, {"slug": "suggestions", "title": "Suggestions", "group": "Watching", "icon": "sparkles", "summary": "Your YouTube feed, minus what's already in your library.", "text": "Suggestions in the sidebar shows videos from YouTube you might want to save, minus ones already in your library. It reads your real YouTube feed through your sign-in, so you need to be signed in . Subscriptions shows new uploads from channels you follow; Recommended shows your YouTube Home. Download on a card saves it to the library chosen in Settings › Suggestions; Open opens it on YouTube. Cards show the approximate download size. Hide Shorts hides Shorts and, by default, any clip under a minute (change the length in Settings › Suggestions). While Suggestions is showing, the toolbar search box searches all of YouTube. Settings › Suggestions can switch the source to the Google Cloud API (advanced) , which needs your own Google Cloud project, and can use it as a fallback if the feed fails."}, {"slug": "getting-videos-out", "title": "Getting videos out", "group": "Sharing and Music", "icon": "share", "summary": "Drag, Share, Save to Downloads, and downloading straight to Downloads.", "text": "Drag a video card to the desktop, a Finder folder or another app to get a copy. The library's own file never moves. Share (right-click, the player's top bar, or full screen) opens the macOS share menu: AirDrop, Messages, Mail, Notes and any share extensions you have. Save to Downloads (right-click) copies the video into ~/Downloads and shows it in Finder. It never overwrites a file that's already there. To download straight to Downloads without adding to a library, choose Downloads Folder in Add Video's \"Save to\" menu."}, {"slug": "wifi-sharing", "title": "Wi-Fi sharing", "group": "Sharing and Music", "icon": "wifi", "summary": "Watch your library on a phone or tablet on the same Wi-Fi.", "text": "Watch your library on a phone, tablet or another computer on the same Wi-Fi, in its browser, with no app to install. Click the globe button in the toolbar and choose Start Local Sharing . Scan the QR code with your phone, or use Copy Link . Pick a library and channel, then tap a video to watch it, with captions. The link contains a random access token, so only people with the link can open it. Regenerate Token makes a new one, and Use Reusable Link keeps the same link between sessions. An address that tries 20 wrong tokens is locked out. The page shows the Mac's battery level, so you know when it needs charging. Click Stop to turn sharing off."}, {"slug": "music", "title": "Music", "group": "Sharing and Music", "icon": "music", "summary": "An optional music player for your own folders of songs.", "text": "Music is optional and off by default. Turn it on in Settings › Music with Enable Music , then choose: One for the whole app: one music collection that shows in every library, kept in the app's own folder. Separate for each library: each library you tick has its own music, stored with that library (handy for music on an external drive). A Music item appears in the sidebar. Click + in the toolbar to add a folder of songs (MP3, M4A, FLAC, WAV and more). Tags and cover art are read automatically. Song files are never moved or changed. Browsing and playlists Songs , Albums , Artists and Playlists views. Sort the song table by any column. Folder Playlists: every added folder is a playlist, and so is every folder inside it that has songs, so a folder of album or playlist folders becomes one playlist each. Collapse a folder's subfolders with its chevron. Made for You: Liked Songs (the heart next to any song), Recently Played and Most Played. Make your own playlists with New Playlist… or right-click songs › Add to Playlist . Playing Double-click a song, or hover its cover and click play. Right-click for Play Next and Add to Queue . The floating player bar has shuffle, previous, play/pause, next, repeat, the progress bar, volume and Up Next , where you can reorder or clear the queue. The bar stays while you browse videos. Right-click it outside Music to hide it until you open Music again, or turn on Hide the music bar when leaving Music . Your keyboard's media keys and Control Center's Now Playing work. Starting a video pauses the music, and the other way round. Your queue and position are restored, paused, when you reopen the app."}, {"slug": "privacy", "title": "Privacy and security", "group": "Help", "icon": "lock", "summary": "What's stored, how it's encrypted, and what the app connects to.", "text": "No accounts, no servers, no analytics. VideoLibrary only connects to the sites you download from (and GitHub, if you install the SABR add-on). Sign-ins and tokens are encrypted with AES-GCM using a key kept in your Mac's Keychain, never stored in plain text. yt-dlp gets a decrypted copy of your cookies in a private temporary folder for each download, which is removed when it finishes. The debug log removes tokens and cookies before writing anything. Because the app is signed by its developer rather than Apple, macOS asks for Keychain access once after each update. Choose Always Allow ."}, {"slug": "troubleshooting", "title": "Troubleshooting", "group": "Help", "icon": "wrench", "summary": "Fixes for the problems people run into most.", "text": "Downloads suddenly fail YouTube changes often. Settings › Tools › Install & Update All fixes most problems. \"Sign in to confirm you're not a bot\" YouTube shows this to some networks, especially VPNs. Sign in , and the app uses your sign-in for these. A video came out in 360p See 360p and SABR . Use Re-download in HD on the video. Suggestions are empty or the sign-in disappeared After an update, macOS asks for Keychain access. If that prompt is denied or closed, the app can't read your saved sign-in until it asks again. Quit and reopen the app and choose Always Allow . Your sign-in is kept while it waits for access. \"Contacting YouTube\" takes a while Signed-in downloads solve YouTube's player challenges first, which can take 10 to 40 seconds on slow or VPN connections. The app won't open the first time Follow step 3 of the install guide . Importing from Safari fails Give VideoLibrary Full Disk Access in System Settings › Privacy & Security, or import from another browser. A library says Disconnected Plug the drive back in. Its videos come back on their own. Still stuck? Open Settings › Help › Open Debug Log and attach it to an issue on GitHub (see best practices )."}, {"slug": "where-files-live", "title": "Where files live", "group": "Help", "icon": "folder", "summary": "Every folder VideoLibrary reads and writes.", "text": "Videos (default library) ~/Movies/VideoLibrary/<uploader>/ A library's index and music <library>/.VideoLibrary/ Imported copies <library>/Imported/ App settings and debug log ~/Library/Application Support/VideoLibrary/ Encrypted sign-ins ~/Library/Application Support/VideoLibrary/secure/ SABR add-on (if installed) ~/Library/Application Support/VideoLibrary/tools/ App-wide music collection ~/Library/Application Support/VideoLibrary/Music/"}];
// Manual search, appended to docs/manual/search.js after the topic list
// (window.MANUAL_TOPICS). On the index it lists matching topics in place of
// the cards; on a topic page it filters the sidebar. "/" focuses the box.
(function () {
  var topics = window.MANUAL_TOPICS || [];
  var input = document.querySelector('[data-manual-search]');
  if (!input) return;

  function score(topic, words) {
    var title = topic.title.toLowerCase(), summary = topic.summary.toLowerCase(), text = topic.text.toLowerCase();
    var total = 0;
    for (var i = 0; i < words.length; i++) {
      var word = words[i];
      if (title.indexOf(word) >= 0) total += 10;
      else if (summary.indexOf(word) >= 0) total += 4;
      else if (text.indexOf(word) >= 0) total += 1;
      else return 0;
    }
    return total;
  }

  function matches(query) {
    var words = query.toLowerCase().split(/\s+/).filter(Boolean);
    return topics
      .map(function (topic) { return { topic: topic, score: score(topic, words) }; })
      .filter(function (match) { return match.score > 0; })
      .sort(function (a, b) { return b.score - a.score; })
      .map(function (match) { return match.topic; });
  }

  // A short bit of the page around the first matching word.
  function snippet(topic, query) {
    var word = query.toLowerCase().split(/\s+/).filter(Boolean)[0] || '';
    var at = topic.text.toLowerCase().indexOf(word);
    if (!word || at < 0 || topic.title.toLowerCase().indexOf(word) >= 0) return topic.summary;
    var start = Math.max(0, at - 60);
    return (start > 0 ? '…' : '') + topic.text.slice(start, at + 110).trim() + '…';
  }

  function escape(text) {
    return text.replace(/[&<>"]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]; });
  }

  var results = document.querySelector('[data-manual-results]');
  var groups = document.querySelectorAll('[data-group]');
  var empty = document.querySelector('[data-manual-empty]');

  function update() {
    var query = input.value.trim();
    var found = query ? matches(query) : topics;
    if (results) {
      // Index page: results replace the grouped cards while searching.
      results.hidden = !query;
      groups.forEach(function (group) { group.hidden = !!query; });
      if (query) {
        results.innerHTML = found.length
          ? '<div class="mcards">' + found.map(function (topic) {
              return '<a class="mcard" href="/manual/' + topic.slug + '"><span class="mcard-icon"><svg class="i"><use href="#' + topic.icon + '"/></svg></span>'
                + '<span><span class="mcard-title">' + escape(topic.title) + '</span><span class="mcard-text">' + escape(snippet(topic, query)) + '</span></span></a>';
            }).join('') + '</div>'
          : '<p class="mresults-empty">Nothing in the manual matches “' + escape(query) + '”.</p>';
      }
      return;
    }
    // Topic page: filter the sidebar.
    var slugs = {};
    found.forEach(function (topic) { slugs[topic.slug] = true; });
    groups.forEach(function (group) {
      var shown = 0;
      group.querySelectorAll('a[data-slug]').forEach(function (link) {
        var keep = !query || slugs[link.dataset.slug];
        link.hidden = !keep;
        if (keep) shown++;
      });
      group.hidden = shown === 0;
    });
    if (empty) empty.hidden = !query || found.length > 0;
  }

  input.addEventListener('input', update);
  input.addEventListener('keydown', function (event) {
    if (event.key === 'Enter') {
      var first = input.value.trim() && matches(input.value.trim())[0];
      if (first) location.href = '/manual/' + first.slug;
    } else if (event.key === 'Escape') {
      input.value = '';
      update();
      input.blur();
    }
  });
  document.addEventListener('keydown', function (event) {
    var target = event.target;
    var typing = target && (target.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(target.tagName));
    if (event.key === '/' && !typing && !event.metaKey && !event.ctrlKey && !event.altKey) {
      event.preventDefault();
      input.focus();
    }
  });
})();
